 */

reg = (volatile uint32_t *)(K1R_SYSCTRL_BASE +
                            K1R_SYSCTRL_UART0_CLK_RST);

*reg = (K1R_CLK_FCLK_SEL_26M << K1R_CLK_FCLK_SEL_SHIFT) |
       (0 << K1R_CLK_FCLK_DIV_SHIFT) |
       K1R_CLK_PCLK_EN |
       K1R_CLK_FCLK_EN |
       K1R_CLK_SW_RSTN;

