/* PXA UART 使能（对齐 esOS pxa_uart_initialize）：
 * IER = RDA(0x01) | RECV_LINE(0x04) | UUE(0x40)
 * MCR = OUT2(0x08)   ← 关键：发送使能，漏掉则 THR 写不生效
 * FCR = 0x07         ← enable + clear RCVR + clear XMIT
 */

K1R_UART_REG(base, K1R_UART_IER_DLM) = 0x01 | 0x04 | K1R_UART_IER_UUE;
K1R_UART_REG(base, K1R_UART_MCR)     = K1R_UART_MCR_OUT2;
K1R_UART_REG(base, K1R_UART_FCR_IIR) = 0x07;

input.new_string:
/* PXA UART 使能：
 * IER = UUE(0x40)，暂不使能接收中断（RDA/RECV_LINE 会在 RX 有噪声时
 *   触发中断风暴，拖垮启动；接收中断待串口接收功能接入时再开）
 * MCR = OUT2(0x08)   ← 关键：发送使能，漏掉则 THR 写不生效
 * FCR = 0x07         ← enable + clear RCVR + clear XMIT
 */

K1R_UART_REG(base, K1R_UART_IER_DLM) = K1R_UART_IER_UUE;
K1R_UART_REG(base, K1R_UART_MCR)     = K1R_UART_MCR_OUT2;
K1R_UART_REG(base, K1R_UART_FCR_IIR) = 0x07;

